                        }

                        else
                        {
                            locationMenuIndex = locations.Count - 1;
                            Speech.Ambient(locations[locationMenuIndex].name);
                        }
                    }

                    if (mainMenuIndex == 1)
                    {
                        if (!shifting)
                        {
                            if (spawnMenuIndex > 0)
